        return ADCS_E_NULL;
    }

    /* 2. Check finiteness */
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            val = candidate->m[i][j];
            if (!isfinite(val)) {
                *repaired = adcs_mat3_identity();
                *correction_norm = INFINITY;
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    /* 3. Check degenerate geometry */
    /* Extract first two rows */
    r0.x = candidate->m[0][0]; r0.y = candidate->m[0][1]; r0.z = candidate->m[0][2];
    r1.x = candidate->m[1][0]; r1.y = candidate->m[1][1]; r1.z = candidate->m[1][2];

    /* Check if first row is zero vector */
    norm_r0 = adcs_vec3_norm(&r0);
    if (norm_r0 <= ADCS_EPS_NORM) {
        *repaired = adcs_mat3_identity();
        *correction_norm = INFINITY;
        return ADCS_E_DEGENERATE;
    }

