    proj_coeff = adcs_vec3_dot(&r1, &x);
    y_temp = adcs_vec3_sub(&r1, &adcs_vec3_scale(&x, proj_coeff));

    if (adcs_vec3_norm(&y_temp) <= ADCS_EPS_COLLINEAR) {
        *repaired = adcs_mat3_identity();
        *correction_norm = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    /* 4. Construct right-handed basis */
    /* Normalize remainder as y */
    if (adcs_vec3_normalize(&y_temp, ADCS_EPS_COLLINEAR, &y) != ADCS_OK) {
        *repaired = adcs_mat3_identity();
        *correction_norm = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    /* Set z = x cross y */
    z = adcs_vec3_cross(&x, &y);

    /* Recompute y = z cross x */
    y = adcs_vec3_cross(&z, &x);

    /* Store x, y, z as rows */
    repaired->m[0][0] = x.x; repaired->m[0][1] = x.y; repaired->m[0][2] = x.z;
    repaired->m[1][0] = y.x; repaired->m[1][1] = y.y; repaired->m[1][2] = y.z;
    repaired->m[2][0] = z.x; repaired->m[2][1] = z.y; repaired->m[2][2] = z.z;

