    adcs_vec3_t row0 = {candidate->m[0][0], candidate->m[0][1], candidate->m[0][2]};
    adcs_vec3_t row1 = {candidate->m[1][0], candidate->m[1][1], candidate->m[1][2]};

    double norm0 = adcs_vec3_norm(&row0);
    if (norm0 <= ADCS_EPS_NORM) {
        *repaired = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t x;
    adcs_status_t st = adcs_vec3_normalize(&row0, ADCS_EPS_NORM, &x);
    if (st != ADCS_OK) {
        *repaired = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    double proj = adcs_vec3_dot(&row1, &x);
    adcs_vec3_t scale_x = adcs_vec3_scale(&x, proj);
    adcs_vec3_t y_temp = adcs_vec3_sub(&row1, &scale_x);
    double norm_y_temp = adcs_vec3_norm(&y_temp);

    if (norm_y_temp <= ADCS_EPS_COLLINEAR) {
        *repaired = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t y;
    st = adcs_vec3_normalize(&y_temp, ADCS_EPS_COLLINEAR, &y);
    if (st != ADCS_OK) {
        *repaired = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t z = adcs_vec3_cross(&x, &y);
    y = adcs_vec3_cross(&z, &x);

    repaired->m[0][0] = x.x; repaired->m[0][1] = x.y; repaired->m[0][2] = x.z;
    repaired->m[1][0] = y.x; repaired->m[1][1] = y.y; repaired->m[1][2] = y.z;
    repaired->m[2][0] = z.x; repaired->m[2][1] = z.y; repaired->m[2][2] = z.z;

    double sum_sq_diff = 0.0;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            double diff = repaired->m[i][j] - candidate->m[i][j];
            sum_sq_diff += diff * diff;
        }
    }
    *correction_norm = sqrt(sum_sq_diff);

    return ADCS_OK;
}
